const { topicImageId } = require('../data/topicImages');
const { READING_DATA } = require('../data/readingData');
const { WRITING_DATA } = require('../data/writingData');
const { LISTENING_DATA, listeningAudioId, buildTranscript, withSpreadAnswers } = require('../data/listeningData');

const topics = [
  // Grammar: backend/data/grammarCurriculum.js (kart resimleriyle birlikte).
  ...grammarTopics.map(({ source, ...topic }) => topic),
];

// Vocabulary: backend/data/vocabularyCurriculum.js (kart resimleriyle birlikte).
const vocabularyTopics = vocabularyCurriculumTopics.map(({ source, ...topic }) => topic);
// Writing / Reading / Listening kart resimleri: data/topicImages.js (seviyedeki sıra + başlık).
const writingTopics = Object.entries(WRITING_DATA).flatMap(([level, items]) =>
  items.map(({ title, passage, instructions }, index) => ({
    title,
    category: 'writing',
    level,
    description: instructions,
    passage,
    image: topicImageId('writing', level, index, title),
  }))
);
const readingTopics = Object.entries(READING_DATA).flatMap(([level, items]) =>
  items.map(({ title, passage }, index) => ({
    title,
    category: 'reading',
    level,
    description: `${title} başlıklı okuma parçası ve anlama soruları.`,
    passage,
    image: topicImageId('reading', level, index, title),
  }))
);
// Listening: data/listeningData.js. passage = transkript (cevaplar kontrol edilince gösterilir),
// audio = TTS ile üretilip Cloudinary'ye yüklenen kaydın public ID'si (npm run generate:listening).
const listeningTopics = Object.entries(LISTENING_DATA).flatMap(([level, items]) =>
  items.map((item, index) => ({
    title: item.title,
    category: 'listening',
    level,
    description: 'Listen to the recording and choose the correct answer for each question.',
    passage: buildTranscript(item),
    audio: listeningAudioId(level, item.slug),
    image: topicImageId('listening', level, index, item.title),
  }))
);

