const placementReadingText1 =
  "Last month, I moved to a new flat in a small town near the coast. At first, I didn't know anyone, so I felt a little lonely. Every morning, I walked to the bakery on the corner to buy fresh bread. The woman who worked there was very friendly, and we often talked about the weather or the local news. After a few weeks, I joined a small gym close to my building. There, I met some neighbours who invited me to a street party. I was nervous about going alone, but everyone was kind and welcoming. Now I know several people in my street, and I feel much happier here. I still buy bread from the same bakery every day, and the woman always remembers my name. Looking back, I realise that these small daily habits made the biggest difference: I no longer feel like a stranger on my own street, and I've even started inviting some of my new friends over for coffee at the weekend.";

