  // Çoktan seçmeli sorular için kısa yardımcı — [başlık, seçenekler, doğru cevap, açıklama]
  // (Exercise 1: dropdown / Exercise 2: seçenek butonları — ikisi de aynı veri şeklini kullanır,
  // görünüm farkı sadece frontend'de exerciseGroup'a göre belirleniyor.)
  const buildMultipleChoice = (topic, exerciseGroup, items) =>
    items.map(([title, options, correctAnswer, explanation]) => ({
      topicId: topic._id,
      level: topic.level,
      exerciseGroup,
      type: 'multiple-choice',
      title,
      options,
      correctAnswer,
      explanation,
    }));

  // Boşluk doldurma / dönüştürme soruları için kısa yardımcı — [başlık, doğru cevap, açıklama]
  const buildFillInBlanks = (topic, exerciseGroup, items) =>
    items.map(([title, correctAnswer, explanation]) => ({
      topicId: topic._id,
      level: topic.level,
      exerciseGroup,
      type: 'fill-in-blanks',
      title,
      correctAnswer,
      explanation,
    }));

  // Reading: her konu tek bir egzersiz (exerciseGroup 1) — 5 çoktan seçmeli okuduğunu anlama sorusu.
  const readingQuestions = Object.entries(READING_DATA).flatMap(([level, items]) =>
    items.flatMap(({ title, questions }) => {
      const topic = createdTopics.find((t) => t.title === title && t.category === 'reading' && t.level === level);
      return buildMultipleChoice(topic, 1, questions);
    })
  );

  // Listening: her konu tek bir egzersiz (exerciseGroup 1) — 5 çoktan seçmeli dinlediğini anlama sorusu.
  const listeningQuestions = Object.entries(LISTENING_DATA).flatMap(([level, items]) =>
    items.flatMap(({ title, questions }) => {
      const topic = createdTopics.find((t) => t.title === title && t.category === 'listening' && t.level === level);
      return buildMultipleChoice(topic, 1, withSpreadAnswers(questions));
    })
  );

  // Writing: her konu tek bir egzersiz (exerciseGroup 1) — kelime kutusundan 10 boşluk doldurma.
  const writingQuestions = Object.entries(WRITING_DATA).flatMap(([level, items]) =>
    items.flatMap(({ title, questions }) => {
      const topic = createdTopics.find((t) => t.title === title && t.category === 'writing' && t.level === level);
      return buildFillInBlanks(topic, 1, questions);
    })
  );

